import { afterEach, expect, it } from 'vitest'
import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { App } from './App'
import { SyncIndicator } from './SyncIndicator'
import { StatusBadge } from './StatusBadge'

afterEach(cleanup)

it('renders visual state immediately and updates it with user actions', () => {
  const { container } = render(<App />)
  const has = (element: Element, name: string) => element.classList.contains(name)
  const inbox = screen.getByTestId('folder-inbox')
  expect(has(inbox, 'is-active')).toBe(true)
  fireEvent.click(screen.getByTestId('folder-sent'))
  expect(has(inbox, 'is-active')).toBe(false)
  expect(has(screen.getByTestId('folder-sent'), 'is-active')).toBe(true)

  for (const name of ['Priority only', 'Compact']) {
    const button = screen.getByRole('button', { name })
    for (const active of [true, false]) {
      fireEvent.click(button)
      expect(has(button, 'is-active')).toBe(active)
      expect(button.getAttribute('aria-pressed')).toBe(String(active))
      if (name === 'Compact') expect(has(container.querySelector('main')!, 'compact')).toBe(active)
    }
  }
  const list = screen.getByRole('button', { name: 'List' })
  const preview = screen.getByRole('button', { name: 'Preview' })
  expect(has(list, 'is-active')).toBe(true)
  fireEvent.click(preview)
  expect(has(list, 'is-active')).toBe(false)
  expect(has(preview, 'is-active')).toBe(true)
  fireEvent.click(list)
  expect(has(list, 'is-active')).toBe(true)
  expect(has(preview, 'is-active')).toBe(false)

  const search = screen.getByRole('searchbox')
  fireEvent.focus(search)
  expect(has(search, 'is-focused')).toBe(true)
  fireEvent.blur(search)
  expect(has(search, 'is-focused')).toBe(false)
})

it('renders unread and online styles from current props', () => {
  const { rerender } = render(<><StatusBadge count={3} /><SyncIndicator online /></>)
  expect(screen.getByTestId('unread-badge').classList.contains('has-unread')).toBe(true)
  expect(screen.getByRole('status').classList.contains('is-online')).toBe(true)
  rerender(<><StatusBadge count={0} /><SyncIndicator online={false} /></>)
  expect(screen.getByTestId('unread-badge').classList.contains('has-unread')).toBe(false)
  expect(screen.getByRole('status').classList.contains('is-online')).toBe(false)
})
